from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}
RECEIPT_PREFIX = {"card": "card:", "transfer": "transfer:"}


def _no_check(member: dict) -> None:
    return None


def _validate_expiry(member: dict) -> str | None:
    if (
        "expired_days" not in member
        or not isinstance(member["expired_days"], int)
        or member["expired_days"] < 0
    ):
        return "bad expiry"
    return None


def _validate_strikes(member: dict) -> str | None:
    if (
        "strikes" not in member
        or not isinstance(member["strikes"], int)
        or member["strikes"] < 0
    ):
        return "bad strikes"
    if member["strikes"] >= MAX_STRIKES:
        return "too many strikes"
    return None


def _resolve_active(member: dict, payment: dict) -> tuple[str, int]:
    return "renewed", TIER_FEES[member["tier"]]


def _resolve_lapsed(member: dict, payment: dict) -> tuple[str, int]:
    if member["expired_days"] <= GRACE_DAYS:
        return "renewed", TIER_FEES[member["tier"]] + LATE_FEE
    return "reinstated", TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE


def _resolve_suspended(member: dict, payment: dict) -> tuple[str, int]:
    fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
    return "reactivated", fee


_STATUS_PLAN = {
    "active": {"check": _no_check, "resolve": _resolve_active},
    "lapsed": {"check": _validate_expiry, "resolve": _resolve_lapsed},
    "suspended": {"check": _validate_strikes, "resolve": _resolve_suspended},
}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member = raw_member
    payment = raw_payment
    if "id" not in member or "status" not in member or "tier" not in member:
        return {"ok": False, "error": "missing member field"}
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return {"ok": False, "error": "bad member id"}

    status = member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}

    plan = _STATUS_PLAN.get(status)
    if plan is None:
        return {"ok": False, "error": "unknown status"}

    if member["tier"] not in TIER_FEES:
        return {"ok": False, "error": "unknown tier"}
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return {"ok": False, "error": "bad amount"}
    if payment["method"] not in RECEIPT_PREFIX:
        return {"ok": False, "error": "unsupported method"}

    specific = plan["check"](member)
    if specific is not None:
        return {"ok": False, "error": specific}

    new_status, fee = plan["resolve"](member, payment)
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    receipt = RECEIPT_PREFIX[payment["method"]] + member["id"] + ":" + new_status + ":" + str(fee)
    return {"ok": True, "status": new_status, "fee": fee, "receipt": receipt}

