        a=('exc',type(e).__name__)
    try:
        b=orig.process_renewal(m.copy(),p.copy())
    except Exception as e:
        b=('exc',type(e).__name__)
    n+=1
    if a!=b:
        print('MISMATCH',m,p,'new=',a,'orig=',b)
        break
else:
    print('all',n,'matched')
